-- Additive, no production personnel or accounting backfill.
CREATE TABLE workplace_clock (id TEXT PRIMARY KEY, version INTEGER NOT NULL DEFAULT 0);
INSERT INTO workplace_clock VALUES ('global',0);
CREATE TABLE workplace_units (id TEXT PRIMARY KEY, name TEXT NOT NULL, legal_entity TEXT NOT NULL, site TEXT NOT NULL, department TEXT NOT NULL, workplace TEXT NOT NULL, timezone TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE workplace_shifts (id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES workplace_units(id), name TEXT NOT NULL, start_minute INTEGER NOT NULL CHECK(start_minute BETWEEN 0 AND 1439), end_minute INTEGER NOT NULL CHECK(end_minute BETWEEN 0 AND 1439), weekdays_json TEXT NOT NULL, grace_in INTEGER NOT NULL DEFAULT 0, grace_out INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE workplace_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), unit_id TEXT NOT NULL REFERENCES workplace_units(id), job_title TEXT NOT NULL, manager_id TEXT REFERENCES users(id), shift_id TEXT REFERENCES workplace_shifts(id), version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE workplace_grants (user_id TEXT NOT NULL REFERENCES users(id), unit_id TEXT NOT NULL REFERENCES workplace_units(id), capability TEXT NOT NULL CHECK(capability IN('hr','manager','finance','executive')), PRIMARY KEY(user_id,unit_id,capability));
CREATE TABLE workplace_events (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL, action TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), detail_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX workplace_events_entity ON workplace_events(entity_id,created_at);
CREATE TABLE attendance_days (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), unit_id TEXT NOT NULL REFERENCES workplace_units(id), work_date TEXT NOT NULL, plan_json TEXT NOT NULL, UNIQUE(user_id,work_date));
CREATE TABLE attendance_punches (id TEXT PRIMARY KEY, day_id TEXT NOT NULL REFERENCES attendance_days(id), kind TEXT NOT NULL CHECK(kind IN('in','out')), punched_at TEXT NOT NULL, UNIQUE(day_id,kind));
CREATE TABLE workplace_requests (id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN('leave','expense')), user_id TEXT NOT NULL REFERENCES users(id), unit_id TEXT NOT NULL REFERENCES workplace_units(id), business_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('submitted','manager_approved','approved','rejected','withdrawn','complete')), version INTEGER NOT NULL DEFAULT 1, data_json TEXT NOT NULL, manager_actor TEXT REFERENCES users(id), reviewer_actor TEXT REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX workplace_request_scope ON workplace_requests(kind,unit_id,status,business_date);
CREATE TABLE workplace_bill_scopes (business_key TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES workplace_units(id), legal_entity TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE workplace_proofs (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES workplace_requests(id), object_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL UNIQUE, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE workplace_payment_links (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES workplace_requests(id), document_id TEXT NOT NULL UNIQUE REFERENCES finance_documents(id), proof_id TEXT NOT NULL UNIQUE REFERENCES workplace_proofs(id), bank_account TEXT NOT NULL, bank_reference TEXT NOT NULL, bank_date TEXT NOT NULL, legal_entity TEXT NOT NULL, UNIQUE(legal_entity,bank_account,bank_reference));
CREATE TABLE workplace_bank_checks (id TEXT PRIMARY KEY, link_id TEXT NOT NULL UNIQUE REFERENCES workplace_payment_links(id), allocation_id TEXT NOT NULL UNIQUE REFERENCES finance_documents(id), actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
