CREATE TRIGGER workplace_expense_closed_insert BEFORE INSERT ON workplace_requests WHEN NEW.kind='expense' AND EXISTS(SELECT 1 FROM finance_period_events p WHERE p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) AND (substr(NEW.business_date,1,7)<=p.month OR substr(json_extract(NEW.data_json,'$.settlementDate'),1,7)<=p.month)) BEGIN SELECT RAISE(ABORT,'closed finance workplace request'); END;
CREATE TRIGGER workplace_expense_closed_update BEFORE UPDATE ON workplace_requests WHEN NEW.kind='expense' AND EXISTS(SELECT 1 FROM finance_period_events p WHERE p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) AND (substr(NEW.business_date,1,7)<=p.month OR substr(json_extract(NEW.data_json,'$.settlementDate'),1,7)<=p.month)) BEGIN SELECT RAISE(ABORT,'closed finance workplace request'); END;
CREATE TRIGGER workplace_payment_links_closed BEFORE INSERT ON workplace_payment_links WHEN EXISTS(SELECT 1 FROM workplace_requests r JOIN finance_period_events p ON p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) WHERE r.id=NEW.request_id AND (substr(r.business_date,1,7)<=p.month OR substr(json_extract(r.data_json,'$.settlementDate'),1,7)<=p.month)) BEGIN SELECT RAISE(ABORT,'closed finance workplace evidence'); END;
CREATE TRIGGER workplace_proofs_closed BEFORE INSERT ON workplace_proofs WHEN EXISTS(SELECT 1 FROM workplace_requests r JOIN finance_period_events p ON p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) WHERE r.id=NEW.request_id AND (substr(r.business_date,1,7)<=p.month OR substr(json_extract(r.data_json,'$.settlementDate'),1,7)<=p.month)) BEGIN SELECT RAISE(ABORT,'closed finance workplace evidence'); END;
